const FOLLOWBOX = "<section class=\"followbox\">\n  <div class=\"st\"><span class=\"k\">SHIFT 팔로우</span><h2>영상으로 보고, 기사로 자세히 읽기</h2><p>30초 영상은 인스타그램과 유튜브 쇼츠에, 그날 나온 소식은 스레드에 가장 먼저 올립니다.</p></div>\n  <div class=\"fbtns\">\n    <a class=\"fbtn\" href=\"https://www.instagram.com/shift_ai_magazine/\" target=\"_blank\" rel=\"noopener\"><b>인스타그램</b><span>@shift_ai_magazine</span></a>\n    <a class=\"fbtn\" href=\"https://www.youtube.com/channel/UCWzwTQoe0q2IdwZV6BuopVw\" target=\"_blank\" rel=\"noopener\"><b>유튜브</b><span>시프트 AI · 쇼츠</span></a>\n    <a class=\"fbtn\" href=\"https://www.threads.com/@shift_ai_magazine\" target=\"_blank\" rel=\"noopener\"><b>스레드</b><span>@shift_ai_magazine</span></a>\n  </div>\n</section>";
